import{_ as t,c as o,o as a,a2 as n}from"./chunks/framework.C0qydWUs.js";const d=JSON.parse('{"title":"Community","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/community.md","filePath":"documentation/community.md","lastUpdated":1784896391000}'),r={name:"documentation/community.md"};function i(s,e,u,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h1><p>The OpenMFP community is the heart of our platform&#39;s development. We believe in fostering an inclusive, collaborative environment where users, developers, and contributors can work together to improve OpenMFP. Whether you&#39;re using OpenMFP, contributing code, or exploring the platform, we encourage you to engage with us.</p><h2 id="github-discussions" tabindex="-1">GitHub Discussions <a class="header-anchor" href="#github-discussions" aria-label="Permalink to &quot;GitHub Discussions&quot;">​</a></h2><p>We have enabled <a href="https://github.com/orgs/openmfp/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>. This is a space where you can connect with other users, ask questions, and share feedback about OpenMFP.</p><h3 id="how-to-participate" tabindex="-1">How to Participate: <a class="header-anchor" href="#how-to-participate" aria-label="Permalink to &quot;How to Participate:&quot;">​</a></h3><ul><li><strong>Ask questions</strong>: Get help, share your challenges, or learn best practices.</li><li><strong>Share ideas</strong>: Suggest features, enhancements, or improvements to the platform.</li><li><strong>Report issues</strong>: Discuss bugs or behaviors before reporting them officially.</li><li><strong>Collaborate</strong>: Engage with other developers, contributors, and users to help shape the future of OpenMFP.</li></ul><h3 id="community-code-of-conduct" tabindex="-1">Community Code of Conduct <a class="header-anchor" href="#community-code-of-conduct" aria-label="Permalink to &quot;Community Code of Conduct&quot;">​</a></h3><p>We strive to maintain a respectful and inclusive environment. Please follow our <a href="https://github.com/openmfp/community/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a> when engaging with the community.</p><p>By participating, you agree to foster a positive, collaborative, and welcoming space for everyone.</p><h2 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h2><p>OpenMFP chat lives on the <a href="https://linuxfoundation.zulipchat.com/" target="_blank" rel="noreferrer">Linux Foundation Zulip server</a>. Two channels cover most conversations.</p><table tabindex="0"><thead><tr><th>Channel</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://linuxfoundation.zulipchat.com/#narrow/channel/neonephos-openmfp-discussion" target="_blank" rel="noreferrer"><code>neonephos-openmfp-discussion</code></a></td><td>Design discussions, RFCs, and general questions about OpenMFP.</td></tr><tr><td><a href="https://linuxfoundation.zulipchat.com/#narrow/channel/neonephos-openmfp-support" target="_blank" rel="noreferrer"><code>neonephos-openmfp-support</code></a></td><td>Help with installing, running, or operating OpenMFP.</td></tr></tbody></table><h3 id="don-t-report-security-issues-in-chat" tabindex="-1">Don&#39;t report security issues in chat <a class="header-anchor" href="#don-t-report-security-issues-in-chat" aria-label="Permalink to &quot;Don&#39;t report security issues in chat&quot;">​</a></h3><p>Posting a vulnerability in public chat exposes it to potential attackers before a fix exists. Please follow our <a href="https://github.com/openmfp/openmfp.org/security/policy" target="_blank" rel="noreferrer">security policy</a> to report it through the project&#39;s private intake.</p><h2 id="stay-updated" tabindex="-1">Stay Updated <a class="header-anchor" href="#stay-updated" aria-label="Permalink to &quot;Stay Updated&quot;">​</a></h2><ul><li><strong>Engage on GitHub Discussions</strong>: Join the conversation and collaborate with the community.</li><li><strong>Chat on Zulip</strong>: Join the <a href="https://linuxfoundation.zulipchat.com/" target="_blank" rel="noreferrer">Linux Foundation Zulip server</a> for real-time discussions.</li></ul>',16)])])}const m=t(r,[["render",i]]);export{d as __pageData,m as default};
